const body = $('Webhook').item.json.body;

const equipments = body.equipment_list.split(',');
const rates = body.client_final_rate.split(',');
const clientId = $input.item.json.client_id;

return equipments.map((equipment, i) => ({
  json: {
    client_id: clientId,
    equipment: equipment.trim(),
    client_final_rate: rates[i].trim(),
    start_time: body.start_time,
    expected_return_time: body.expected_return_time
  }
}));

const body = $('Webhook').item.json.body;
const dispatchIds = body.all_dispatch_ids.split(',');
const rentalIds = $input.all().map(item => item.json.rental_id);
const clientId = $('Execute a SQL query2').item.json.client_id;

return dispatchIds.map((dispatch_id, i) => ({
  json: {
    dispatch_id: dispatch_id.trim(),
    rental_id: rentalIds[i],
    client_id: clientId
  }
}));

const body = $('Webhook').item.json.body;
const equipments = body.equipment_list.split(',');
const rates = body.client_final_rate.split(',');

return equipments.map((equipment, i) => ({
  json: {
    deal_name: equipment.trim(),
    amount: rates[i].trim(),
    close_date: body.expected_return_time,
    start_date: body.start_time
  }
}));

const body = $('Webhook').item.json.body;

const equipments = body.equipment_list.split(',');
const rates = body.client_final_rate.split(',');
const baseRates = body.vendor_base_rate.split(',');
const markups = body.markup_amount.split(',');

let equipmentBreakdown = equipments.map((eq, i) => {
  return `• ${eq.trim().toUpperCase()}
  - Vendor Rate: $ ${baseRates[i].trim()}
  - Markup: $ ${markups[i].trim()}
  - Final Rate: $ ${rates[i].trim()}`;
}).join('\n');

const startDate = new Date(body.start_time).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
const endDate = new Date(body.expected_return_time).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

const message = `🚀 *NEW DISPATCH CONFIRMED*

*CUSTOMER PROFILE*
- Name: ${body.customer_name}
- Email: ${body.customer_email}
- Phone: ${body.customer_phone}
- Location: ${body.city}

*BOOKING SCHEDULE*
- Start Date: ${startDate}
- End Date: ${endDate}

*VENDOR DETAILS*
- Company: ${body.vendor_name}
- Contact: ${body.vendor_phone}
- Email: ${body.vendor_email}

*EQUIPMENT BREAKDOWN*
${equipmentBreakdown}`;

return [{ json: { message } }];

